+		{envGitHubToken, GitHub},
+		{envGitLabToken, Gitlab},
+		{envAzureDevOpsUserName, AzureDevOps},
+		{envSourcehutToken, Sourcehut},
+	}
+
+	for _, p := range tokenProviders {
