   322	// checkProvider validates a single provider's credentials. It returns the
   323	// number of fully-configured provider entries it found (0 or 1) and any
   324	// partial-configuration errors so the caller can surface them rather than
   325	// terminating the process from a library function.
   326	func checkProvider(provider string) (int, error) {
   327		var outputErrs strings.Builder
   328	
   329		var count int
   330	
   331		if slices.Contains(justTokenProviders, provider) {
   332			count += checkJustTokenProvider(provider, &outputErrs)
   333		}
   334	
   335		if slices.Contains(userAndPasswordProviders, provider) {
   336			count += checkUserAndPasswordProvider(provider, &outputErrs)
   337		}
   338	
   339		if outputErrs.Len() > 0 {
   340			return count, errors.New(outputErrs.String())
   341		}
   342	
   343		return count, nil
   344	}
