   367	// checkUserAndPasswordProvider returns 1 if all of the provider's auth
   368	// parameters are set, recording the missing ones when only some are.
   369	func checkUserAndPasswordProvider(provider string, outputErrs *strings.Builder) int {
   370		var foundCount, totalCount int
   371	
   372		for _, param := range enabledProviderAuth[provider] {
   373			totalCount++
   374	
   375			val, exists := GetEnvOrFile(param)
   376			if exists && strings.Trim(val, " ") != "" {
   377				foundCount++
   378			}
   379		}
   380	
   381		if foundCount > 0 && foundCount < totalCount {
   382			for _, param := range enabledProviderAuth[provider] {
   383				val, exists := GetEnvOrFile(param)
   384				if !exists || strings.Trim(val, " ") == "" {
   385					_, _ = fmt.Fprintf(outputErrs, "%s parameter '%s' is not defined.\n", provider, param)
   386				}
   387			}
   388		}
   389	
   390		if foundCount == totalCount {
   391			return 1
   392		}
   393	
   394		return 0
   395	}
